#!/usr/bin/env python3
"""Single entry point for every Knowledge-Engineering gate arm.

The arms are separately runnable and each one is exactly what CI invokes, so a
local run and a CI run execute the same command:

===================================  ==================================================
arm                                  what it checks
===================================  ==================================================
``links``                            relative Markdown link and image targets resolve
``python``                           tracked Python files compile
``notebooks``                        tracked notebooks are output-free JSON
``checkpoints``                      no Jupyter checkpoint file is tracked
``archive``                          the four archive arms over one file listing
``tests``                            the gate's own unit tests
``gnn``                              pinned GNN parser and sketch/exemplar conformance
``fast`` (default)                   ``archive`` + ``tests``; what CI's docs job runs
``full``                             ``fast`` + ``gnn``; the whole gate
``timings``                          measure each arm once, rewrite docs/gate-timings.md
===================================  ==================================================

``gnn`` is the only arm that needs the network and third-party packages: it
installs the distribution pinned in ``.github/gnn-pin.json`` when ``--install``
is given. ``full`` combines the offline arms with it.

There is no separate lint or type arm because the repository has no linter or
type-checker configuration: the archive checks are the only static analysis it
defines, and they are not replaced by an unconfigured tool.
"""

from __future__ import annotations

import argparse
import datetime as dt
import platform
import subprocess
import sys
import time
import unittest
from pathlib import Path

SCRIPTS = Path(__file__).resolve().parent
ROOT = SCRIPTS.parents[1]

import archive_checks  # noqa: E402  (sibling module, resolved from the script directory)
import gnn_conformance  # noqa: E402

ARCHIVE_ARMS = ("links", "python", "notebooks", "checkpoints")
TIMINGS_DOC = Path("docs") / "gate-timings.md"
TIMINGS_MARKER = (
    "<!-- generated by `python .github/scripts/gate.py timings`; "
    "edit the generator, not this file -->"
)

DESCRIPTIONS = {
    "links": "relative Markdown link and image targets resolve inside the repository",
    "python": "tracked Python files compile under the running interpreter",
    "notebooks": "tracked notebooks are valid JSON with no committed outputs",
    "checkpoints": "no Jupyter checkpoint file is tracked",
    "archive": "all four archive checks over one `git ls-files` read",
    "tests": "the gate's own dependency-free unit tests",
    "gnn": "pinned GNN parser, sketch parsing, and type checking",
    "fast": "archive checks plus tests; the default arm and CI's docs job",
    "full": "the fast arm plus the pinned GNN conformance arm",
    "timings": "measure each offline arm once and rewrite the generated timings page",
}
ARM_ORDER = (
    "links",
    "python",
    "notebooks",
    "checkpoints",
    "archive",
    "tests",
    "gnn",
    "fast",
    "full",
    "timings",
)


def command_for(arm: str) -> str:
    """Return the documented command line for ``arm``."""
    return f"python .github/scripts/gate.py {arm}"


def _report(label: str, inspected: int, errors: list[str], note: str = "") -> int:
    if errors:
        print(f"{label}: {len(errors)} check(s) failed:", file=sys.stderr)
        for error in errors:
            print(f"- {error}", file=sys.stderr)
        return 1
    summary = f"{label}: ok ({inspected} tracked files"
    summary += f"; {note}" if note else ""
    print(f"{summary})")
    return 0


def arm_archive(names: tuple[str, ...], label: str) -> int:
    inspected, errors = archive_checks.run(names, ROOT)
    notes = {
        "links": "links resolve",
        "python": "Python compiles",
        "notebooks": "notebooks are output-free JSON",
        "checkpoints": "no checkpoints",
    }
    note = "; ".join(notes[name] for name in names)
    return _report(label, inspected, errors, note)


def arm_tests() -> int:
    suite = unittest.TestLoader().discover(
        str(SCRIPTS / "tests"), top_level_dir=str(SCRIPTS)
    )
    total = suite.countTestCases()
    if not total:
        print("tests: no test cases were discovered", file=sys.stderr)
        return 1
    result = unittest.TextTestRunner(verbosity=1, stream=sys.stdout).run(suite)
    if not result.wasSuccessful():
        return 1
    print(f"tests: ok ({total} tests)")
    return 0


def run_arm(arm: str, *, install: bool = False) -> int:
    """Run one arm and return its exit status."""
    if arm in ARCHIVE_ARMS:
        return arm_archive((arm,), arm)
    if arm == "archive":
        return arm_archive(ARCHIVE_ARMS, "archive")
    if arm == "tests":
        return arm_tests()
    if arm == "gnn":
        return gnn_conformance.run(ROOT, install_first=install)
    if arm == "fast":
        return 0 if arm_archive(ARCHIVE_ARMS, "archive") == 0 and arm_tests() == 0 else 1
    if arm == "full":
        if arm_archive(ARCHIVE_ARMS, "archive") != 0 or arm_tests() != 0:
            return 1
        return gnn_conformance.run(ROOT, install_first=install)
    raise ValueError(f"unknown arm: {arm}")


def _measure(arm: str) -> float:
    started = time.perf_counter()
    result = subprocess.run(
        [sys.executable, str(Path(__file__).resolve()), arm],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )
    elapsed = time.perf_counter() - started
    if result.returncode != 0:
        sys.stdout.write(result.stdout)
        sys.stderr.write(result.stderr)
        raise SystemExit(f"timings: arm {arm!r} failed; fix it before measuring")
    return elapsed


def timings_arms() -> tuple[str, ...]:
    """The arms the generated timings page measures."""
    return tuple(arm for arm in ARM_ORDER if arm not in {"gnn", "full", "timings"})


def render_timings(rows: list[tuple[str, float]], gnn_seconds: float | None) -> str:
    """Render the generated timings page."""
    implementation = platform.python_implementation()
    version = platform.python_version()
    lines = [
        TIMINGS_MARKER,
        "# Gate arm timings",
        "",
        "Wall time for one run of each arm on this host, measured "
        f"{dt.datetime.now(dt.UTC).strftime('%Y-%m-%d')} with "
        f"{implementation} {version} on {platform.system()} "
        f"{platform.machine()}. These are single local samples, not CI "
        "guarantees: GitHub Actions uses different hardware and also pays for "
        "checkout and interpreter setup.",
        "",
        "| Arm | Command | Wall time |",
        "| --- | --- | --- |",
    ]
    for arm, seconds in rows:
        lines.append(f"| `{arm}` | `{command_for(arm)}` | {seconds:.2f} s |")
    lines += [
        "",
        "## Interpreter-specific arms",
        "",
        "`gnn` is measured separately because it installs third-party packages "
        "and reads the network, so its duration depends on the package cache "
        "and mirror.",
    ]
    if gnn_seconds is None:
        lines.append(
            "It was not measured for this page: the pinned parser was not "
            "importable in the measuring interpreter."
        )
    else:
        lines.append(
            f"With the pinned parser already installed it took {gnn_seconds:.2f} s "
            "for one conformance check, excluding the install step; the install "
            "step's duration depends on pip's cache. Refresh this page from an "
            "interpreter that has the parser installed to record it again."
        )
    return "\n".join(lines) + "\n"


def write_timings(output: Path, *, include_gnn: bool) -> int:
    arms = timings_arms()
    # The `tests` arm asserts that this page lists every measured arm, and `fast`
    # runs it, so a first generation would otherwise measure itself into a
    # failure. Write a provisional page, measure, then replace it with the
    # measured one; restore the previous bytes if measuring fails.
    previous = output.read_text(encoding="utf-8") if output.is_file() else None
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(
        render_timings([(arm, 0.0) for arm in arms], None), encoding="utf-8"
    )
    try:
        rows = [(arm, _measure(arm)) for arm in arms]
        gnn_seconds: float | None = _measure("gnn") if include_gnn else None
        document = render_timings(rows, gnn_seconds)
    except BaseException:
        if previous is None:
            output.unlink(missing_ok=True)
        else:
            output.write_text(previous, encoding="utf-8")
        raise
    output.write_text(document, encoding="utf-8")
    print(document)
    print(f"timings: wrote {output}")
    return 0


def parsers() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="gate.py",
        description="Run one gate arm; every arm is what CI runs.",
    )
    parser.add_argument(
        "arm",
        nargs="?",
        default="fast",
        choices=ARM_ORDER,
        help="arm to run (default: fast)",
    )
    parser.add_argument(
        "--install",
        action="store_true",
        help="install the pinned GNN parser before the gnn or full arm",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=ROOT / TIMINGS_DOC,
        help="destination of the generated timings page (timings arm only)",
    )
    parser.add_argument(
        "--include-gnn",
        action="store_true",
        help="also measure the gnn arm (timings arm only; needs the parser)",
    )
    parser.add_argument(
        "--list", action="store_true", help="list the arms and their commands"
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    options = parsers().parse_args(argv)
    if options.list:
        width = max(len(arm) for arm in ARM_ORDER)
        for arm in ARM_ORDER:
            print(f"{arm:<{width}}  {command_for(arm)}")
            print(f"{'':<{width}}  {DESCRIPTIONS[arm]}")
        return 0
    if options.install and options.arm not in {"gnn", "full"}:
        print("gate.py: --install is only valid for the gnn and full arms", file=sys.stderr)
        return 2
    if options.arm == "timings":
        return write_timings(options.output, include_gnn=options.include_gnn)
    return run_arm(options.arm, install=options.install)


if __name__ == "__main__":
    raise SystemExit(main())
